    if not sample and name and code: watch=[(name,code,f"{price:,.0f}" if isinstance(price,(int,float)) else "—","")]
    rows="".join(f"<div class='row'><div><b>{html.escape(n)}</b><small>{c}</small></div><strong>{p}</strong><em>{ch}</em></div>" for n,c,p,ch in watch)
