    news_rows="".join(f"<div class='news'><span class='thumb'>{n[:2]}</span><div><b>{t}</b><small>{n} · {a}</small></div></div>" for n,t,a in news)
    years=report.get("years") or []
    vals=[float(x.get("profit") or 0) for x in years] or [1,2,2.5,3,4,5,6]
    lo,hi=min(vals),max(vals); span=hi-lo or 1
    d="M "+" L ".join(f"{4+i*92/max(1,len(vals)-1):.1f},{38-((v-lo)/span)*30:.1f}" for i,v in enumerate(vals))
